<!doctype html>
<html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#10130f"><title>ZARAFSHON — Admin boshqaruvi</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet"><style>
:root{--bg:#10130f;--panel:#191e17;--panel2:#20271e;--cream:#f6f0e5;--gold:#d7ad64;--gold2:#f1d59a;--muted:#a8ad9f;--line:rgba(241,213,154,.17);--red:#e98278;--green:#9acb9b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 90% 0,rgba(75,92,54,.2),transparent 35%),var(--bg);color:var(--cream);font-family:'DM Sans',sans-serif;line-height:1.55}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}.layout{min-height:100vh;display:grid;grid-template-columns:250px minmax(0,1fr)}aside{padding:28px 20px;border-right:1px solid var(--line);background:rgba(15,18,14,.85);position:sticky;top:0;height:100vh;display:flex;flex-direction:column}.brand{font:700 1.15rem 'Playfair Display';letter-spacing:.15em;color:var(--gold2)}.brand small{display:block;font:500 .62rem 'DM Sans';letter-spacing:.28em;color:var(--muted);margin-top:5px}.side-label{margin:42px 10px 12px;color:#7e8778;font-size:.65rem;letter-spacing:.2em;text-transform:uppercase}.navitem{display:flex;align-items:center;gap:12px;padding:13px 14px;border-radius:9px;color:var(--muted);font-size:.88rem;margin-bottom:5px;transition:.25s}.navitem.active,.navitem:hover{background:rgba(215,173,100,.12);color:var(--gold2)}.sidebottom{margin-top:auto;border-top:1px solid var(--line);padding-top:18px;color:var(--muted);font-size:.78rem}.sidebottom strong{color:var(--cream);display:block;font-size:.9rem;margin:4px 0 14px}.logout{border:0;background:none;color:var(--muted);padding:0;cursor:pointer}.logout:hover{color:var(--red)}main{padding:30px clamp(18px,4vw,54px) 60px;min-width:0}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:36px}.crumb{font-size:.72rem;text-transform:uppercase;letter-spacing:.18em;color:var(--gold)}h1,h2,h3{font-family:'Playfair Display',serif;font-weight:500}h1{font-size:clamp(2rem,4vw,3rem);margin:8px 0 0}h1 em{color:var(--gold2);font-weight:500}.top-right{display:flex;align-items:center;gap:12px}.avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#6e5730,#273b2b);border:1px solid var(--line);color:var(--gold2);font-weight:700}.user small{display:block;color:var(--muted);font-size:.72rem}.btn{display:inline-flex;justify-content:center;align-items:center;gap:8px;border:1px solid var(--gold);background:transparent;color:var(--gold2);padding:11px 16px;cursor:pointer;transition:.25s;font-size:.82rem;border-radius:5px}.btn:hover,.btn.primary{background:var(--gold);color:#17170f}.btn.danger{border-color:rgba(233,130,120,.5);color:var(--red)}.btn.danger:hover{background:var(--red);color:#1c100f}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:30px}.stat{padding:23px;background:linear-gradient(145deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:12px;position:relative;overflow:hidden;transition:transform .25s}.stat:hover{transform:translateY(-4px)}.stat:after{content:"";position:absolute;width:100px;height:100px;right:-35px;top:-35px;border-radius:50%;background:rgba(215,173,100,.08)}.stat label{font-size:.76rem;color:var(--muted)}.stat strong{display:block;font:600 clamp(1.6rem,3vw,2.4rem) 'Playfair Display';margin-top:8px;color:var(--gold2)}.stat span{font-size:.72rem;color:var(--muted)}.columns{display:grid;grid-template-columns:minmax(280px,.82fr) minmax(0,1.4fr);gap:20px;align-items:start}.panel{background:rgba(25,30,23,.92);border:1px solid var(--line);border-radius:12px;padding:24px;min-width:0}.panel-head{display:flex;justify-content:space-between;align-items:start;gap:15px;margin-bottom:20px}.panel h2{font-size:1.45rem;margin:0}.sub{font-size:.8rem;color:var(--muted);margin-top:5px}.field{margin-bottom:15px}.field label{display:block;font-size:.75rem;color:var(--muted);margin-bottom:7px}.field input,.field select,.field textarea,.search{width:100%;background:#11150f;border:1px solid rgba(241,213,154,.18);border-radius:6px;padding:12px 13px;color:var(--cream);outline:none;transition:border-color .2s}.field textarea{min-height:90px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus,.search:focus{border-color:var(--gold)}.field input[type=file]{font-size:.75rem}.field small{display:block;color:#899184;margin-top:6px;font-size:.7rem}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.notice{padding:13px 16px;border-radius:7px;margin-bottom:22px;border:1px solid rgba(154,203,155,.3);background:rgba(154,203,155,.08);color:var(--green);font-size:.88rem}.errors{padding:13px 16px;border-radius:7px;margin-bottom:22px;border:1px solid rgba(233,130,120,.3);background:rgba(233,130,120,.08);color:#f3aaa3;font-size:.85rem}.list-tools{display:flex;gap:10px;margin-bottom:16px}.search{flex:1;min-width:0}.count{font-size:.75rem;color:var(--muted);white-space:nowrap;align-self:center}.dish-list{display:grid;gap:12px}.dish{padding:16px;background:#151a13;border:1px solid rgba(241,213,154,.12);border-radius:9px;transition:border-color .2s}.dish:hover{border-color:var(--line)}.dish-top{display:flex;align-items:center;gap:14px}.thumb{width:64px;height:64px;flex:0 0 64px;border-radius:7px;background:linear-gradient(135deg,#34452e,#382a1a);display:grid;place-items:center;overflow:hidden;font-size:1.7rem}.thumb img{width:100%;height:100%;object-fit:cover}.dish-info{min-width:0;flex:1}.dish-info h3{font-size:1.05rem;margin:0 0 3px;overflow-wrap:anywhere}.dish-info p{margin:0;color:var(--muted);font-size:.75rem}.dish-price{font-weight:700;color:var(--gold2);white-space:nowrap;font-size:.9rem}.dish-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px;padding-top:12px;border-top:1px solid rgba(241,213,154,.1)}details.edit{margin-top:12px}details.edit summary{cursor:pointer;color:var(--gold2);font-size:.78rem;list-style:none}details.edit summary::-webkit-details-marker{display:none}details.edit summary:before{content:'＋ ';font-size:1rem}details.edit[open] summary:before{content:'− '}.editform{margin-top:15px;padding-top:15px;border-top:1px solid var(--line)}.empty{text-align:center;color:var(--muted);padding:35px 10px;border:1px dashed var(--line);border-radius:8px}.footer-note{margin-top:24px;color:#737d6d;font-size:.72rem}.mobile-title{display:none}@media(max-width:1050px){.layout{grid-template-columns:210px minmax(0,1fr)}.columns{grid-template-columns:1fr}.stats{gap:10px}.panel{padding:20px}}@media(max-width:700px){.layout{display:block}aside{position:relative;height:auto;padding:17px 20px;border-right:0;border-bottom:1px solid var(--line);display:block}.side-label,.navitem,.sidebottom{display:none}.brand{font-size:1rem}main{padding:24px 16px 45px}.top{align-items:flex-start}.top-right .user{display:none}.stats{grid-template-columns:1fr;gap:10px}.stat{padding:17px}.stat strong{font-size:1.8rem}.panel{padding:17px}.dish-top{align-items:flex-start}.dish-price{font-size:.8rem}.two{grid-template-columns:1fr 1fr}.btn{padding:10px 12px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition-duration:.01ms!important;animation-duration:.01ms!important}}
</style></head><body><div class="layout"><aside><a class="brand" href="{{ route('site') }}">ZARAFSHON<small>ADMIN CONTROL CENTER</small></a><div class="side-label">Boshqaruv</div><a class="navitem active" href="#overview">◈ &nbsp; Umumiy ko‘rinish</a><a class="navitem" href="#taomlar">▦ &nbsp; Menyu va taomlar</a><a class="navitem" href="{{ route('site') }}">↗ &nbsp; Saytni ko‘rish</a><div class="sidebottom">Tizimga kirilgan foydalanuvchi<strong>{{ auth()->user()->name }}</strong><form action="{{ route('logout') }}" method="POST">@csrf<button class="logout" type="submit">↪ Tizimdan chiqish</button></form></div></aside>
