<script>
const search=document.getElementById('dishSearch'),items=[...document.querySelectorAll('.dish')],shown=document.getElementById('shownCount'),none=document.getElementById('noResults');if(search){search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase();let n=0;items.forEach(item=>{const match=item.dataset.name.includes(q);item.style.display=match?'':'none';if(match)n++});shown.textContent=n+' ta';if(none)none.style.display=n===0&&items.length?'block':'none'})}
